                return LarkPage(data: r.data, hasMore: r.data?.hasMore ?? false, nextPageToken: r.data?.pageToken)
            }
        }

        /// 获取面试评价信息（新版）
        ///
        /// 获取面试评价详细信息，如面试结论、面试得分和面试官等信息（含模块评价）。
        ///
        /// - SeeAlso: <https://open.feishu.cn/api-explorer?from=op_doc_tab&apiName=get&project=hire&resource=interview_record&version=v2>
        ///
        /// `GET /open-apis/hire/v2/interview_records/:interview_record_id`
        public func get(interviewRecordId: String, params: LarkHire.Hire.WebsiteDeliveryCreateByResumeQuery = .init(), options: RequestOptions = .none) async throws -> LarkResponse<LarkHire.Hire.InterviewRecordGetResponseV2> {
            try await client.request(.get, "/open-apis/hire/v2/interview_records/\(LarkURL.escapePathSegment(interviewRecordId))", query: params, body: .none, options: options)
        }

    }
}
